class Solution {
public:
    string makeLargestSpecial(string s) {
        if (s.empty()) return "";
        vector<string> parts;
        int cnt = 0, start = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] == '1') cnt++;
            else cnt--;
            if (cnt == 0) {
                string inner = makeLargestSpecial(s.substr(start + 1, i - start - 1));
                parts.push_back("1" + inner + "0");
                start = i + 1;
            }
        }
        sort(parts.begin(), parts.end(), [](const string& a, const string& b) {
            return a > b;
        });
        string res;
        for (const auto& p : parts) res += p;
        return res;
    }
};
